<?php
declare(strict_types=1);
require __DIR__.'/common.php';$u=cloud_user();$public=($_GET['public']??'')==='1';$d=db();
$sql='SELECT p.*,u.username,(SELECT COUNT(*) FROM z6_playlistdatabase x WHERE x.idpl=p.idpl) AS songs FROM z6_playlistname p JOIN z6_users u ON u.id=p.idu WHERE '.($public?'p.public=1':'p.idu=?').' ORDER BY p.datetime DESC,p.idpl DESC';$s=$d->prepare($sql);if(!$public)$s->bind_param('i',$u['id']);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$d->close();head($public?'Publiczne playlisty':'Moje playlisty');music_toolbar($public?'playlists.php?public=1':'playlists.php');
?>
<?php if(!$public): ?><section class="card mb-4"><div class="card-body p-4"><h2 class="h5 mb-3">Nowa playlista</h2><form method="post" action="music_action.php" class="row g-3 align-items-end" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(music_csrf())?>"><input type="hidden" name="action" value="create_playlist"><div class="col-12 col-md-6"><label class="form-label" for="playlist-name">Nazwa</label><input class="form-control" name="name" id="playlist-name" maxlength="160" required></div><div class="col-12 col-md-3"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" id="new-public" name="public" value="1"><label class="form-check-label" for="new-public">Publiczna</label></div></div><div class="col-12 col-md-9"><label class="form-label" for="playlist-cover">Okładka (opcjonalnie)</label><input class="form-control" type="file" id="playlist-cover" name="cover" accept="image/png,image/jpeg,image/webp"></div><div class="col-12 col-md-3"><button class="btn btn-primary w-100" type="submit">Utwórz playlistę</button></div></form></div></section><?php endif; ?>
<div class="row g-3"><?php foreach($rows as $p): ?><div class="col-12 col-md-6 col-lg-4"><article class="card music-playlist h-100"><div class="card-body p-4"><?=music_cover_html(null,(int)$p['idpl'],$p['coverfilename'],'Okładka '.$p['name'])?><span class="badge <?=$p['public']?'text-bg-success':'text-bg-secondary'?> mb-3"><?=$p['public']?'Publiczna':'Prywatna'?></span><h2 class="h5"><a href="playlist.php?id=<?=$p['idpl']?>"><?=h($p['name'])?></a></h2><p class="text-body-secondary mb-1"><?=h($p['username'])?> · <?=$p['songs']?> utworów</p><p class="small text-body-secondary"><?=h(cloud_time($p['datetime']))?></p><a class="btn btn-outline-primary" href="playlist.php?id=<?=$p['idpl']?>">Otwórz playlistę</a></div></article></div><?php endforeach; ?></div>
<?php if(!$rows): ?><p class="text-body-secondary">Brak playlist.</p><?php endif; ?>
<?php foot(); ?>
